:root
{
  --bg: #0f1419;
  --surface: #1a2332;
  --border: #2d3a4f;
  --text: #e6edf3;
  --muted: #8b9cb3;
  --accent: #3d8bfd;
  --accent-hover: #5ca0ff;
  --healthy: #3fb950;
  --unhealthy: #f85149;
  --warning: #d29922;
  --font: system-ui, -apple-system, "Segoe UI", sans-serif;
  --mono: ui-monospace, "SF Mono", Menlo, monospace;
  --radius: 6px;
  --space: 1rem;
}

*
{
  box-sizing: border-box;
}

body
{
  margin: 0;
  font-family: var(--font);
  font-size: 15px;
  line-height: 1.5;
  color: var(--text);
  background: var(--bg);
}

code
{
  font-family: var(--mono);
  font-size: 0.9em;
}

.page
{
  max-width: 80rem;
  margin: 0 auto;
  padding: calc(var(--space) * 1.5);
}

.header h1
{
  margin: 0 0 0.25rem;
  font-size: 1.5rem;
}

.subtitle
{
  margin: 0 0 var(--space);
  color: var(--muted);
}

.card
{
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: var(--space);
  margin-bottom: var(--space);
}

.card-header
{
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space);
  margin-bottom: var(--space);
}

.card-header h2
{
  margin: 0;
  font-size: 1.1rem;
}

.card-actions
{
  display: flex;
  gap: 0.5rem;
}

.grid
{
  display: grid;
  gap: var(--space);
}

.status-pane
{
  display: grid;
  gap: var(--space);
}

.status-strip
{
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(10rem, 1fr));
  gap: 0.75rem;
}

.status-item
{
  display: flex;
  flex-direction: column;
  gap: 0.15rem;
}

.status-label
{
  font-size: 0.75rem;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--muted);
}

.status-value
{
  font-weight: 600;
}

.status-value.ok
{
  color: var(--healthy);
}

.status-value.warn
{
  color: var(--warning);
}

.status-value.bad
{
  color: var(--unhealthy);
}

.btn
