    container: container,
    wsUrl: wsUrl,
    root: root,
    statusBar: statusBar,
    transcript: transcript,
    messageNodes: new Map(),
    panelExpanded: new Map(),
    pendingFrame: null,
    _owned: owned,
  };

  function TrackListener(target, type, handler) {
