test("ACTIVITY_SNAPSHOT replacement and ACTIVITY_DELTA patching", () => {
  const state = createChatState();
  const messageId = "activity-1";

  ReduceAll(state, [
    {
      type: "ACTIVITY_SNAPSHOT",
      messageId,
      activityType: "codex.file_change",
