test("run lifecycle and caught_up status", () => {
  const state = createChatState();
  const runId = "run-1";

  ReduceAll(state, [
    { type: "RUN_STARTED", runId, threadId: "thread-1" },
    { type: "TEXT_MESSAGE_START", messageId: "m1", role: "user" },
