      this.CONNECTING = 0;
      this.CLOSING = 2;
      this.CLOSED = 3;
      this.listeners = {};
    }

    addEventListener(type, handler) {
      this.listeners[type] = handler;
    }

    removeEventListener(type) {
      delete this.listeners[type];
    }

    close() {
      closed = true;
      this.readyState = 3;
    }
  }

  const LiveChatView = LoadChatView({ WebSocket: RecordingWebSocket });
