    events: [
      { type: "TEXT_MESSAGE_CONTENT", messageId: "scroll-1", delta: " more" },
    ],
  });
  handle.transcript.scrollHeight = 2000;
  renderChat(handle);
  assert.equal(handle.transcript.scrollTop, 400);
});

